package com.finguard;
import com.finguard.config.*;import com.finguard.model.*;import com.finguard.service.*;import com.finguard.util.*;import org.junit.jupiter.api.Test;import java.math.*;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class RiskAnalysisServiceTest {Transaction t(String ref,String amount,int minute){return new Transaction(null,"ACCT-X",ref,new BigDecimal(amount),"INR",TransactionType.DEBIT,"Demo Shop",LocalDateTime.of(2026,1,1,10,minute),TransactionStatus.COMPLETED,0,RiskLevel.LOW,List.of());}@Test void highValueIsFlagged(){var x=new RiskAnalysisService(AppConfig.defaults()).evaluate(t("r","6000",0),List.of());assertTrue(x.riskScore()>0);assertTrue(x.reasons().get(0).contains("High-value"));}@Test void rapidAndRepeatedAreFlagged(){var s=new RiskAnalysisService(AppConfig.defaults());var hist=List.of(t("1","100",1),t("2","100",2));var x=s.evaluate(t("3","100",3),hist);assertTrue(x.reasons().stream().anyMatch(r->r.startsWith("Rapid")));assertTrue(x.reasons().stream().anyMatch(r->r.startsWith("Repeated")));}@Test void dailyLimitFlags(){var s=new RiskAnalysisService(AppConfig.defaults());var hist=List.of(t("1","6000",1));assertTrue(s.evaluate(t("2","5000",2),hist).reasons().stream().anyMatch(r->r.startsWith("Daily")));}@Test void scoreCappedAndLevelClassified(){var x=new RiskAnalysisService(AppConfig.defaults()).evaluate(t("r","30000",0),List.of(t("a","30000",1),t("b","30000",2),t("c","30000",3)));assertTrue(x.riskScore()<=100);assertEquals(RiskLevel.HIGH,x.riskLevel());}@Test void inputValidationRejectsNegativeAndBadType(){assertThrows(IllegalArgumentException.class,()->InputValidator.validate("a","r",new BigDecimal("-1"),"INR",TransactionType.DEBIT,"m",LocalDateTime.now()));assertThrows(IllegalArgumentException.class,()->InputValidator.type("wire"));}}
